App/styles.less:
@font-face {
  font-family: 'PlusJakartaSans';
  src: url('/assets/fonts/PlusJakartaSans.ttf') format('truetype');
}
@font-face {
  font-family: 'TwemojiFlags';
  src: url('/assets/fonts/TwemojiFlags.woff2') format('woff2');
  unicode-range: U+1F1E6-1F1FF;
}
:global {
  /* Copyright (C) 2017-2023 Smart code 203358507 */
}
:global :global(.animation-fade-in) {
  animation-timing-function: ease-in-out;
  animation-duration: 350ms;
}
:global :global(.animation-fade-in) :local {
  animation-name: fade-in;
}
@media (prefers-reduced-motion) {
  :global :global(.animation-fade-in) :local {
    animation-name: fade-in-no-motion;
  }
}
@keyframes fade-in {
  0% {
    opacity: 0;
    transform: translateY(4px);
  }
  40% {
    opacity: 0;
    transform: translateY(4px);
  }
  70% {
    opacity: 0.6;
    transform: translateY(2px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}
:global :global(.animation-slide-up) {
  animation-timing-function: ease-out;
  animation-duration: 0.1s;
}
:global :global(.animation-slide-up) :local {
  animation-name: slide-up;
}
@keyframes slide-up {
  0% {
    transform: translateY(100%);
  }
  100% {
    transform: translateY(0%);
  }
}
:global .slide-left-enter {
  transform: translateX(100%);
}
:global .slide-left-active {
  transform: translateX(0%);
  transition: transform 0.3s cubic-bezier(0.32, 0, 0.67, 0);
}
:global .slide-left-exit {
  transform: translateX(100%);
}
:global .slide-up-enter {
  transform: translateY(100%);
}
:global .slide-up-active {
  transform: translateY(0%);
  transition: transform 0.3s cubic-bezier(0.32, 0, 0.67, 0);
}
:global .slide-up-exit {
  transform: translateY(100%);
}
:global .fade-enter {
  opacity: 0;
}
:global .fade-active {
  opacity: 1;
  transition: opacity 0.1s cubic-bezier(0.32, 0, 0.67, 0);
}
:global .fade-exit {
  opacity: 0;
}
@keyframes fade-in-no-motion {
  0% {
    opacity: 0;
  }
  40% {
    opacity: 0;
  }
  70% {
    opacity: 0.6;
  }
  100% {
    opacity: 1;
  }
}
:global .routes-container {
  position: relative;
  z-index: 0;
  height: 100%;
  width: 100%;
}
:global .routes-container .route-container {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 0;
}
:global .routes-container .route-container:not(:last-child) {
  display: none;
}
@media (pointer: coarse) {
  :global .routes-container[data-navigation="push"] .route-container:last-child {
    animation: route-enter 0.2s ease-out;
  }
}
@keyframes route-enter {
  from {
    opacity: 0;
    transform: translateY(0.5rem);
  }
}
@media (prefers-reduced-motion: reduce) {
  :global .routes-container[data-navigation="push"] .route-container:last-child {
    animation: none;
  }
}
:global .routes-container .route-container .route-content {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 0;
  overflow: hidden;
}
:global .routes-container .route-container .modals-container {
  width: 0;
  height: 0;
}
:global .routes-container .route-container .modals-container .modal-container {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 1;
  overflow: hidden;
}
:root {
  --landscape-shape-ratio: 0.5625;
  --poster-shape-ratio: 1.464;
  --scroll-bar-size: 6px;
  --horizontal-nav-bar-size: 5.5rem;
  --vertical-nav-bar-size: 6rem;
  --focus-outline-size: 2px;
  --color-facebook: #1877F1;
  --color-x: #000000;
  --color-reddit: #FF4500;
  --color-imdb: #f5c518;
  --color-trakt: #ffffff;
  --color-placeholder: #60606080;
  --color-placeholder-text: hsla(0, 0%, 75%, 0.5);
  --color-placeholder-background: hsla(0, 0%, 50%, 0.2);
  --primary-background-color: #0c0b11;
  --secondary-background-color: #1a173e;
  --primary-foreground-color: rgba(255, 255, 255, 0.9);
  --secondary-foreground-color: #0c0b11;
  --primary-accent-color: #7b5bf5;
  --secondary-accent-color: #22b365;
  --tertiary-accent-color: #f6c700;
  --quaternary-accent-color: #1245a6;
  --overlay-color: rgba(255, 255, 255, 0.05);
  --modal-background-color: #0f0d20;
  --outer-glow: 0px 0px 15px rgba(123, 91, 245, 0.37);
  --warning-accent-color: #ffa500;
  --danger-accent-color: #dc2626;
  --border-radius: 0.75rem;
  --top-overlay-size: 5.25rem;
  --bottom-overlay-size: 0rem;
  --overlap-size: 3rem;
  --transparency-gradient-pad: 6rem;
  --safe-area-inset-top: env(safe-area-inset-top, 0rem);
  --safe-area-inset-right: env(safe-area-inset-right, 0rem);
  --safe-area-inset-bottom: env(safe-area-inset-bottom, 0rem);
  --safe-area-inset-left: env(safe-area-inset-left, 0rem);
  --dynamic-viewport-width: 100vw;
  --dynamic-viewport-height: 100vh;
  --large-viewport-width: 100vw;
  --large-viewport-height: 100vh;
  --small-viewport-width: 100vw;
  --small-viewport-height: 100vh;
  --viewport-height-diff: calc(100vh - 100vh);
}
@supports (height: 100dvh) {
  :root {
    --dynamic-viewport-width: 100dvw;
    --dynamic-viewport-height: 100dvh;
  }
}
@supports (height: 100lvh) {
  :root {
    --large-viewport-width: 100lvw;
    --large-viewport-height: 100lvh;
  }
}
@supports (height: 100svh) {
  :root {
    --small-viewport-width: 100svw;
    --small-viewport-height: 100svh;
  }
}
@supports (height: 100lvh) and (height: 100svh) {
  :root {
    --viewport-height-diff: calc(100lvh - 100svh);
  }
}
@media (display-mode: standalone) {
  :root {
    --safe-area-inset-bottom: min(env(safe-area-inset-bottom, 0rem), max(1rem, calc(var(--viewport-height-diff) - env(safe-area-inset-top, 0rem))));
  }
}
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  font-size: 1rem;
  font-family: inherit;
  border: none;
  outline: none;
  list-style: none;
  user-select: none;
  text-decoration: none;
  appearance: none;
  background: none;
  box-shadow: none;
  overflow: hidden;
  word-break: break-word;
  scrollbar-width: thin;
  scrollbar-color: var(--overlay-color) transparent;
}
::-webkit-scrollbar {
  width: var(--scroll-bar-size);
  height: var(--scroll-bar-size);
}
::-webkit-scrollbar-thumb {
  border-radius: var(--scroll-bar-size);
  background-color: var(--overlay-color);
}
::-webkit-scrollbar-thumb:hover {
  background-color: var(--primary-accent-color);
}
::-webkit-scrollbar-track {
  background-color: transparent;
}
svg {
  overflow: visible;
}
::view-transition-old(root),
::view-transition-new(root) {
  animation-duration: 0.15s;
}
html {
  width: calc(max(var(--small-viewport-width), var(--dynamic-viewport-width)));
  height: calc(max(var(--small-viewport-height), var(--dynamic-viewport-height)));
  font-family: 'PlusJakartaSans', 'Arial', 'Helvetica', 'TwemojiFlags', 'sans-serif';
  overflow: auto;
  overscroll-behavior: none;
  user-select: none;
  touch-action: manipulation;
  background-color: var(--primary-background-color);
  -webkit-tap-highlight-color: transparent;
}
@media (display-mode: standalone) {
  html {
    width: calc(max(100%, var(--large-viewport-width)));
    height: calc(max(100%, var(--large-viewport-height)));
    -webkit-touch-callout: none;
  }
}
html body {
  width: 100%;
  height: 100%;
  background: linear-gradient(41deg, var(--primary-background-color) 0%, var(--secondary-background-color) 100%);
  -webkit-font-smoothing: antialiased;
}
html body :global(#app) {
  position: relative;
  z-index: 0;
  width: 100%;
  height: 100%;
}
html body :global(#app) .toasts-container {
  position: absolute;
  top: calc(1.2 * var(--horizontal-nav-bar-size) + var(--safe-area-inset-top));
  right: var(--safe-area-inset-right);
  bottom: calc(1.2 * var(--horizontal-nav-bar-size) + var(--safe-area-inset-bottom, 0rem));
  left: auto;
  z-index: 1;
  padding: 0 calc(0.5 * var(--horizontal-nav-bar-size));
  overflow: visible;
  scrollbar-width: none;
  pointer-events: none;
}
html body :global(#app) .toasts-container::-webkit-scrollbar {
  display: none;
}
html body :global(#app) .tooltip-container {
  height: 2.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 1.5rem;
  font-size: 1rem;
  color: var(--primary-foreground-color);
  border-radius: var(--border-radius);
  background-color: var(--modal-background-color);
  box-shadow: var(--outer-glow);
  transition: opacity 0.1s ease-out;
}
html body :global(#app) .updater-banner-container {
  z-index: 1;
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
}
@media only screen and (max-width: 640px) {
  html body :global(#app) .updater-banner-container {
    left: 0.5rem;
    right: 0.5rem;
    bottom: calc(var(--vertical-nav-bar-size) + var(--safe-area-inset-bottom) + 0.5rem);
  }
}
@media only screen and (min-width: 2800px) {
  html {
    font-size: 18px;
  }
}
@media only screen and (max-width: 2800px) {
  html {
    font-size: 16px;
  }
}
@media only screen and (max-width: 2200px) {
  html {
    font-size: 15px;
  }
}
@media only screen and (max-width: 1600px) {
  html {
    font-size: 14px;
  }
}
@media only screen and (max-width: 1000px) {
  html body :global(#app) .toasts-container {
    padding: 0 1rem;
  }
  html body :global(#app) .tooltip-container {
    display: none;
  }
}
@media only screen and (max-width: 640px) {
  :root {
    --bottom-overlay-size: 6rem;
  }
}

components/ActionMenu/ActionMenu.less:
.trigger {
  -webkit-touch-callout: none;
  cursor: pointer;
}
.layer {
  position: fixed;
  z-index: 1;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
}
.menu-container {
  position: fixed;
  min-width: 9rem;
  max-width: min(14rem, calc(100vw - 1rem));
  max-height: min(calc(3rem * 7), calc(100vh - 1rem));
  overflow-y: auto;
  border-radius: var(--border-radius);
  background-color: var(--modal-background-color);
  box-shadow: var(--outer-glow);
  cursor: auto;
}
.menu-container .option-container {
  display: flex;
  flex-direction: row;
  align-items: center;
  width: 100%;
  padding: 1rem 1.5rem;
  text-align: left;
  color: var(--primary-foreground-color);
  cursor: pointer;
}
.menu-container .option-container:hover,
.menu-container .option-container:focus {
  background-color: var(--overlay-color);
}
.menu-container .option-container .label {
  flex: 1;
  max-height: 4.8em;
  font-weight: 500;
  opacity: 0.8;
}

components/NavBar/HorizontalNavBar/style:
.horizontal-nav-bar-container {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  height: var(--horizontal-nav-bar-size);
  padding-right: 1rem;
  background-color: transparent;
  overflow: visible;
  padding-top: var(--safe-area-inset-top);
  box-sizing: content-box;
}
.horizontal-nav-bar-container .logo-container {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--vertical-nav-bar-size);
  height: var(--horizontal-nav-bar-size);
}
.horizontal-nav-bar-container .logo-container .logo {
  flex: none;
  width: 2.5rem;
  height: 2.5rem;
  object-position: center;
  object-fit: contain;
  opacity: 0.9;
}
.horizontal-nav-bar-container .back-button-container {
  margin-left: max(0rem, calc(1rem - var(--safe-area-inset-left)));
}
.horizontal-nav-bar-container .title {
  flex: 4 0 0;
  padding: 0 1rem;
  font-size: 1.2rem;
  font-style: normal;
  font-weight: 500;
  letter-spacing: 0.01rem;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: hsla(222.8, 100%, 78%, 0.9);
}
.horizontal-nav-bar-container .search-bar {
  height: 3.25rem;
  width: 30rem;
}
.horizontal-nav-bar-container .buttons-container {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 0.5rem 0.5rem;
  overflow: visible;
}
.horizontal-nav-bar-container .hdr-indicator {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 3.5rem;
  padding: 0 0.5rem;
  opacity: 0.6;
  user-select: none;
}
.horizontal-nav-bar-container .hdr-indicator .icon {
  flex: none;
  width: 3rem;
  height: 1.5rem;
  color: var(--primary-foreground-color);
  opacity: 0.6;
}
.horizontal-nav-bar-container .button-container {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 3.5rem;
  height: 3.5rem;
  border-radius: 0.75rem;
  opacity: 0.6;
}
.horizontal-nav-bar-container .button-container .icon {
  flex: none;
  width: 2rem;
  height: 2rem;
  color: var(--primary-foreground-color);
  opacity: 0.6;
}
.horizontal-nav-bar-container .button-container:global(.active) {
  background-color: var(--overlay-color);
  opacity: 1;
}
.horizontal-nav-bar-container .button-container:global(.active) .icon {
  color: var(--primary-foreground-color);
  opacity: 0.8;
}
@media (pointer: fine) {
  .horizontal-nav-bar-container .button-container:hover {
    background-color: var(--overlay-color);
    opacity: 1;
  }
  .horizontal-nav-bar-container .button-container:hover .icon {
    color: var(--primary-foreground-color);
    opacity: 0.8;
  }
}
@media only screen and (max-width: 640px) {
  .horizontal-nav-bar-container {
    justify-content: space-between;
    padding-right: 0;
  }
  .horizontal-nav-bar-container .logo-container {
    width: var(--horizontal-nav-bar-size);
  }
  .horizontal-nav-bar-container .button-container {
    margin: 0 1rem;
  }
  .horizontal-nav-bar-container .button-container:not(.back-button-container):not(.menu-button-container) {
    display: none;
  }
}

routes/MetaDetails/styles.less:
.metadetails-container {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  padding-left: var(--safe-area-inset-left);
  padding-right: var(--safe-area-inset-right);
  box-sizing: border-box;
}
.metadetails-container .background-image-layer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: -1;
  background-color: var(--modal-background-color);
}
.metadetails-container .background-image-layer .background-image {
  pointer-events: none;
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: right;
  opacity: 0.3;
}
.metadetails-container .nav-bar {
  z-index: 1;
  flex: none;
  align-self: stretch;
}
.metadetails-container .metadetails-content {
  flex: 1;
  align-self: stretch;
  position: relative;
  z-index: 0;
  display: flex;
  flex-direction: row;
  margin-top: calc(var(--top-overlay-size) * -1);
  padding-top: var(--top-overlay-size);
  padding-bottom: var(--safe-area-inset-bottom, 0rem);
}
.metadetails-container .metadetails-content .meta-message-container {
  align-self: stretch;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem;
  width: 100%;
  height: 100%;
}
.metadetails-container .metadetails-content .meta-message-container .image {
  flex: none;
  width: 12rem;
  height: 12rem;
  max-width: 100%;
  margin-bottom: 1rem;
  object-fit: contain;
  object-position: center;
  opacity: 0.9;
}
.metadetails-container .metadetails-content .meta-message-container .message-label {
  flex: none;
  align-self: stretch;
  font-size: 2rem;
  text-align: center;
  color: var(--primary-foreground-color);
}
.metadetails-container .metadetails-content .meta-preview {
  flex: 0 1 auto;
  align-self: stretch;
  padding: 0 4rem 2rem 4rem;
  padding-left: max(1rem, calc(4rem - var(--safe-area-inset-left)));
}
.metadetails-container .metadetails-content .spacing {
  flex: 1;
}
.metadetails-container .metadetails-content .videos-list,
.metadetails-container .metadetails-content .streams-list {
  flex: 0 0 30rem;
  align-self: stretch;
  border-radius: var(--border-radius) 0 0 var(--border-radius);
  background-color: rgba(12, 11, 17, 0.95);
}
@supports (backdrop-filter: blur(1px)) {
  .metadetails-container .metadetails-content .videos-list,
  .metadetails-container .metadetails-content .streams-list {
    background-color: rgba(0, 0, 0, 0.4);
    backdrop-filter: blur(15px);
  }
}
@media screen and (max-width: 1000px) and (max-height: 500px) and (orientation: landscape) {
  .metadetails-container .metadetails-content .meta-preview {
    padding: 0 1.5rem 1rem;
  }
}
@media only screen and (max-width: 640px) {
  .metadetails-container .background-image-layer .background-image {
    object-position: center;
  }
  .metadetails-container .metadetails-content {
    display: block;
    overflow-y: auto;
    padding-top: calc(var(--top-overlay-size) + var(--safe-area-inset-top));
  }
  .metadetails-container .metadetails-content .spacing {
    display: none;
  }
  .metadetails-container .metadetails-content .meta-preview {
    padding: 0 1.5rem 2rem;
  }
  .metadetails-container .metadetails-content .videos-list,
  .metadetails-container .metadetails-content .streams-list {
    border-radius: var(--border-radius) var(--border-radius) 0 0;
  }
}
